const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const assert = require('node:assert/strict');
const root = path.resolve(__dirname, '..');
function workspace(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'fwa-contract-check-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return dir;
}
function cli(file, args) { return spawnSync(process.execPath, [path.join(root, file), ...args], { encoding:'utf8', windowsHide:true, timeout:5000 }); }
function success(result) { assert.equal(result.status, 0, result.stderr); }
module.exports = { fs, path, assert, workspace, cli, success };

