const test=require('node:test');
const {fs,path,assert,workspace,cli,success}=require('./helpers.cjs');
test('valid batch produces ordered records and per-currency totals',t=>{
 const dir=workspace(t),input=path.join(dir,'in.json'),output=path.join(dir,'manifest.json');
 const orders=[{id:'two',customer:'Bee',amountCents:200,currency:'USD'},{id:'one',customer:'A',amountCents:125,currency:'CNY'},{id:'three',customer:'C',amountCents:50,currency:'USD'}];
 fs.writeFileSync(input,JSON.stringify(orders));success(cli('src/orders/compile.cjs',[input,output]));
 assert.deepEqual(JSON.parse(fs.readFileSync(output,'utf8')),{schemaVersion:1,orders,totalsByCurrency:{CNY:125,USD:250}});
});
for(const [field,bad] of [['id',{id:'keep'}],['customer',{customer:'  '}],['amountCents',{amountCents:-1}],['currency',{currency:'EUR'}]])test('bad '+field+' leaves existing manifest byte-for-byte unchanged',t=>{
 const dir=workspace(t),input=path.join(dir,'in.json'),output=path.join(dir,'manifest.json');
 const good={id:'keep',customer:'A',amountCents:10,currency:'CNY'},second={id:'bad',customer:'B',amountCents:30,currency:'USD',...bad};
 fs.writeFileSync(input,JSON.stringify([good,second]));fs.writeFileSync(output,'previous accepted manifest');
 const result=cli('src/orders/compile.cjs',[input,output]);assert.notEqual(result.status,0);
 const errors=JSON.parse(result.stderr).errors;assert.ok(errors.some(error=>error.row===2&&error.field===field&&typeof error.code==='string'));
 assert.equal(fs.readFileSync(output,'utf8'),'previous accepted manifest');
});

