const test=require('node:test');
const {fs,path,assert,workspace}=require('./helpers.cjs');
const {renderReceipts}=require('../src/receipts/render.cjs');
test('reader follows the actual manifest order and escapes customer text',t=>{
 const dir=workspace(t),file=path.join(dir,'manifest.json');
 const orders=[{id:'z',customer:'<script>x</script>',amountCents:507,currency:'USD'},{id:'a',customer:'Alice & Bob',amountCents:1234,currency:'CNY'}];
 fs.writeFileSync(file,JSON.stringify({schemaVersion:1,orders,totalsByCurrency:{USD:507,CNY:1234}}));
 const html=renderReceipts(file);assert.match(html,/USD\s*5\.07/);assert.match(html,/CNY\s*12\.34/);
 assert.ok(!html.includes('<script>'));assert.ok(html.includes('&lt;script&gt;x&lt;/script&gt;'));assert.ok(html.includes('Alice &amp; Bob'));
 assert.ok(html.indexOf('&lt;script&gt;')<html.indexOf('Alice &amp; Bob'));
});

