const test=require('node:test');
const assert=require('node:assert/strict');
const {retentionDays}=require('../src/settings/archive.cjs');
test('archive configuration validates range and preserves its input',()=>{
 const defaults={other:'keep'};assert.equal(retentionDays(defaults),30);assert.deepEqual(defaults,{other:'keep'});
 for(const value of [1,30,365]){const config={retentionDays:value};assert.equal(retentionDays(config),value);assert.deepEqual(config,{retentionDays:value});}
 for(const value of [0,366,1.5,'30',null]){const config={retentionDays:value};assert.throws(()=>retentionDays(config));assert.deepEqual(config,{retentionDays:value});}
});

