projectFiles.checks/translation-import.test.cjs:
const test=require('node:test');
const {fs,path,assert,workspace,cli,success}=require('./helpers.cjs');
test('raw translation import produces the portable catalog and remains compatible',t=>{
 const dir=workspace(t),input=path.join(dir,'input.json'),output=path.join(dir,'catalog.json');
 const entries=[{locale:'en',key:'hello',text:'Hello'},{locale:'zh',key:'hello',text:'你好'},{locale:'en',key:'bye',text:'Bye'}];
 fs.writeFileSync(input,JSON.stringify(entries));success(cli('src/i18n/import.cjs',[input,output]));
 assert.deepEqual(JSON.parse(fs.readFileSync(output,'utf8')),{schemaVersion:1,locales:{en:{hello:'Hello',bye:'Bye'},zh:{hello:'你好'}}});
});
for(const entry of [{locale:'en',key:'hello',text:'Duplicate'},{locale:'zh',key:' ',text:'Hello'},{locale:'zh',key:'new',text:' '}])test('invalid import preserves old catalog: '+JSON.stringify(entry),t=>{
 const dir=workspace(t),input=path.join(dir,'input.json'),output=path.join(dir,'catalog.json');
 fs.writeFileSync(input,JSON.stringify([{locale:'en',key:'hello',text:'Hello'},entry]));fs.writeFileSync(output,'old catalog');
 assert.notEqual(cli('src/i18n/import.cjs',[input,output]).status,0);assert.equal(fs.readFileSync(output,'utf8'),'old catalog');
});

