const test=require('node:test');
const {fs,path,assert,workspace}=require('./helpers.cjs');
const {lookup}=require('../src/i18n/query.cjs');
test('query consumes supplied catalog and follows locale/en/key fallback',t=>{
 const dir=workspace(t),file=path.join(dir,'catalog.json');
 fs.writeFileSync(file,JSON.stringify({schemaVersion:1,locales:{en:{hello:'Hello',bye:'Bye'},zh:{hello:'你好'}}}));
 assert.equal(lookup(file,'zh','hello'),'你好');assert.equal(lookup(file,'zh','bye'),'Bye');assert.equal(lookup(file,'fr','hello'),'Hello');assert.equal(lookup(file,'fr','missing'),'missing');
 fs.writeFileSync(file,JSON.stringify({schemaVersion:1,locales:{en:{hello:'Changed'}}}));assert.equal(lookup(file,'en','hello'),'Changed');
});

