const test=require('node:test');
const {fs,path,assert,workspace,cli,success}=require('./helpers.cjs');
test('standalone validation CLI emits portable valid report',t=>{
 const dir=workspace(t),input=path.join(dir,'input.json'),output=path.join(dir,'report.json'),entries=[{locale:'en',key:'x',text:'X'}];
 fs.writeFileSync(input,JSON.stringify(entries));success(cli('src/i18n/validate.cjs',[input,output]));
 assert.deepEqual(JSON.parse(fs.readFileSync(output,'utf8')),{schemaVersion:1,valid:true,entries,errors:[]});
});
test('standalone report includes every invalid row and remains usable without importing a catalog',t=>{
 const dir=workspace(t),input=path.join(dir,'input.json'),output=path.join(dir,'report.json');
 const entries=[{locale:'zh',key:'',text:''},{locale:'en',key:'a',text:'A'},{locale:'en',key:'a',text:'Again'}];fs.writeFileSync(input,JSON.stringify(entries));
 const result=cli('src/i18n/validate.cjs',[input,output]);assert.notEqual(result.status,0);
 const report=JSON.parse(fs.readFileSync(output,'utf8'));assert.equal(report.valid,false);assert.deepEqual(report.entries,entries);
 for(const [row,field] of [[1,'key'],[1,'text'],[3,'key']])assert.ok(report.errors.some(error=>error.row===row&&error.field===field&&typeof error.code==='string'));
 assert.equal(fs.existsSync(path.join(dir,'catalog.json')),false);
});

