const test=require('node:test');
const {fs,path,assert,workspace,cli,success}=require('./helpers.cjs');
test('standalone catalog builder consumes a generated report rather than the raw source',t=>{
 const dir=workspace(t),input=path.join(dir,'input.json'),report=path.join(dir,'report.json'),output=path.join(dir,'catalog.json');
 fs.writeFileSync(input,JSON.stringify([{locale:'en',key:'a',text:'A'},{locale:'zh',key:'a',text:'甲'}]));success(cli('src/i18n/validate.cjs',[input,report]));fs.unlinkSync(input);
 success(cli('src/i18n/build-catalog.cjs',[report,output]));assert.deepEqual(JSON.parse(fs.readFileSync(output,'utf8')),{schemaVersion:1,locales:{en:{a:'A'},zh:{a:'甲'}}});
});
test('invalid report cannot overwrite an existing catalog',t=>{
 const dir=workspace(t),report=path.join(dir,'report.json'),output=path.join(dir,'catalog.json');
 fs.writeFileSync(report,JSON.stringify({schemaVersion:1,valid:false,entries:[],errors:[{row:1,field:'text',code:'empty'}]}));fs.writeFileSync(output,'old catalog');
 assert.notEqual(cli('src/i18n/build-catalog.cjs',[report,output]).status,0);assert.equal(fs.readFileSync(output,'utf8'),'old catalog');
});
